browserEvents.LeftShift.onEvent(browserEvents.KeyEvent.Released, function () {
    Render.moveWithController(3, 2, 2)
})
controller.up.onEvent(ControllerButtonEvent.Pressed, function () {
    music.play(music.createSong(hex``), music.PlaybackMode.LoopingInBackground)
    Render.moveWithController(3, 2, 2)
})
controller.down.onEvent(ControllerButtonEvent.Released, function () {
    Render.moveWithController(3, 2, 2)
    music.stopAllSounds()
})
browserEvents.onWheel(function (dx, dy, dz) {
    if (dy > 0) {
        for (let index = 0; index < dy / 2; index++) {
            // You might choose to switch these depending on which control scheme you are used to
            miniMenu.scrollMenus(miniMenu.MenuScroll.Down)
        }
    } else if (dy < 0) {
        for (let index = 0; index < Math.abs(dy) / 2; index++) {
            miniMenu.scrollMenus(miniMenu.MenuScroll.Up)
        }
    }
})
