myMenu.onButtonPressed(controller.A, function (selection, selectedIndex) {
    if (selectedIndex == 0) {
        Delete_menu()
        create_game()
        Render.getRenderSpriteInstance().setPosition(blockSettings.readNumber("px"), blockSettings.readNumber("py"))
        Render.setAttribute(Render.attribute.dirX, blockSettings.readNumber("dx"))
        Render.setAttribute(Render.attribute.dirY, blockSettings.readNumber("dy"))
        Render.setViewMode(ViewMode.raycastingView)
        Render.getRenderSpriteInstance().setFlag(SpriteFlag.Invisible, false)
    }
    if (selectedIndex == 1) {
        Delete_menu()
        create_game()
        blockSettings.clear()
        Render.setViewMode(ViewMode.raycastingView)
        Render.getRenderSpriteInstance().setFlag(SpriteFlag.Invisible, false)
    }
    if (selectedIndex == 2) {
        Delete_menu()
        create_optionsmenu()
    }
    if (selectedIndex == 3) {
        Delete_menu()
        create_quitmenu()
    }
})
game.onUpdate(function () {
    if (GameStarted == true) {
        timer.throttle("action", 5000, function () {
            mySprite.setPosition(randint(0, 260), randint(0, 220))
        })
    }
})
forever(function () {
    if (GameStarted == true) {
        if (Render.getRenderSpriteInstance().tileKindAt(TileDirection.Center, assets.tile`transparency16`)) {
            blockSettings.writeNumber("px", Render.getRenderSpriteInstance().x)
            blockSettings.writeNumber("py", Render.getRenderSpriteInstance().y)
            blockSettings.writeNumber("dx", Render.getAttribute(Render.attribute.dirX))
            blockSettings.writeNumber("dy", Render.getAttribute(Render.attribute.dirY))
        }
        if (browserEvents.G.isPressed()) {
            blockSettings.writeNumber("px", Render.getRenderSpriteInstance().x)
            blockSettings.writeNumber("py", Render.getRenderSpriteInstance().y)
            blockSettings.writeNumber("dx", Render.getAttribute(Render.attribute.dirX))
            blockSettings.writeNumber("dy", Render.getAttribute(Render.attribute.dirY))
        }
        centerX = GamePlayer.x + 2
        centerY = GamePlayer.y + 17
        dx = Render.getAttribute(Render.attribute.dirX)
        dy = Render.getAttribute(Render.attribute.dirY)
        Interact_Point.x = centerX + dx * 20
        Interact_Point.y = centerY + dy * 20
        Interact_Point_2.x = centerX + dx * 30
        Interact_Point_2.y = centerY + dy * 30
        Interact_Point_3.x = centerX + dx * 40
        Interact_Point_3.y = centerY + dy * 40
    }
})
forever(function () {
    if (GameStarted) {
        if (Interact_Point.overlapsWith(NPC_Pedestrian) || (Interact_Point_2.overlapsWith(NPC_Pedestrian) || Interact_Point_3.overlapsWith(NPC_Pedestrian))) {
            Press_E.setFlag(SpriteFlag.Invisible, false)
            Press_E.setFlag(SpriteFlag.RelativeToCamera, true)
            Press_E.setPosition(72, 95)
        } else {
            Press_E.setFlag(SpriteFlag.Invisible, true)
        }
    }
})
